_web = {}
_lang = {"code": "es"}


def _load_web():
    if _web:
        return
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "strings_web.json")
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)
    for code, d in raw.items():
        _web[code] = {k: _clean(v) for k, v in d.items()}


def _clean(v):
    if isinstance(v, str):
        v = v.replace("⏱️ ", "").replace("⚙️ ", "").replace("&middot;", "·").replace("&larr;", "←").replace("&rarr;", "→")
        return re.sub(r"</?b>", "", v)
    return v


def _load_extra(code):
    if code not in _extra:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "locales", code + ".json")
        try:
            with open(path, "r", encoding="utf-8") as f:
                raw = json.load(f)
            _extra[code] = {k: _clean(v) for k, v in raw.items()} if isinstance(raw, dict) else {}
        except (OSError, ValueError):
            _extra[code] = {}                # sin archivo: se usa inglés
    return _extra[code]


def set_language(code):
    _lang["code"] = code if code in _VALID else "es"


def language():
    return _lang["code"]


def get(key, code=None, default=None):
    """Valor crudo (str o lista) del idioma pedido, con respaldo a español."""
    _load_web()
    code = code or _lang["code"]
    if code not in _IDX:                          # idiomas de locales/*.json: si falta la clave, inglés
        val = _load_extra(code).get(key)
        return val if val is not None else get(key, "en", default)
    if key in NEW:
        return NEW[key][_IDX[code]] or NEW[key][0]
    for c in (code, "es"):
        if key in _web.get(c, {}):
            return _web[c][key]
    return default if default is not None else key


def t(key, **fmt):
    val = get(key)
    if isinstance(val, str) and fmt:
        try:
            return val.format(**fmt)
        except (KeyError, IndexError):
            return val
    return val


def locale_date_format():
    """Formato strftime de fecha+hora aproximado al de cada idioma."""
    return {"es": "%d-%m-%Y %H:%M:%S", "en": "%m/%d/%Y %I:%M:%S %p", "fr": "%d/%m/%Y %H:%M:%S",
            "pt": "%d/%m/%Y %H:%M:%S", "zh": "%Y/%m/%d %H:%M:%S", "de": "%d.%m.%Y %H:%M:%S",
            "it": "%d/%m/%Y %H:%M:%S", "nl": "%d-%m-%Y %H:%M:%S", "ru": "%d.%m.%Y %H:%M:%S",
            "ja": "%Y/%m/%d %H:%M:%S", "ko": "%Y. %m. %d. %H:%M:%S"}[_lang["code"]]


MONTHS = {
    "es": ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"],
    "en": ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
    "fr": ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"],
    "pt": ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"],
    "zh": [f"{i}月" for i in range(1, 13)],
    "de": ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"],
    "it": ["gennaio", "febbraio", "marzo", "aprile", "maggio", "giugno", "luglio", "agosto", "settembre", "ottobre", "novembre", "dicembre"],
    "nl": ["januari", "februari", "maart", "april", "mei", "juni", "juli", "augustus", "september", "oktober", "november", "december"],
    "ru": ["январь", "февраль", "март", "апрель", "май", "июнь", "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь"],
    "ja": [f"{i}月" for i in range(1, 13)],
    "ko": [f"{i}월" for i in range(1, 13)],
}
# Nombre del mes dentro de una fecha completa ("5 ноября 2026"): en ruso va en genitivo
MONTHS_IN_DATE = {"ru": ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"]}
# Idiomas CJK: la fecha se escribe año-mes-día con sufijos y sin espacios
_CJK_DATE = {"zh": "{y}年{m}月{d}日", "ja": "{y}年{m}月{d}日", "ko": "{y}년 {m}월 {d}일"}


def date_label(d, long=False):
    """Fecha corta en el idioma activo ('3 nov 2026', '2026年11月3日')."""
    code = _lang["code"]
    if code in _CJK_DATE:
        return _CJK_DATE[code].format(y=d.year, m=d.month, d=d.day)
    names = MONTHS_IN_DATE.get(code) or MONTHS[code]
    name = names[d.month - 1]
    name = name if long else name[:3].lower()
    return f"{d.day} {name} {d.year}"


def month_label(year, month):
    name = MONTHS[_lang["code"]][month - 1]
    code = _lang["code"]
    if code in ("zh", "ja"):
        return f"{year}年{name}"
    if code == "ko":
        return f"{year}년 {name}"
    return f"{name} {year}"
